code_example.css:
body { font-family: sans-serif; background: #f3f8ff; color: #222; padding: 20px; line-height: 1.5; max-width: 560px; }
h1, h2 { margin: 4px 0; }
h2 { color: #1a5fb4; }
header { background: rgb(26, 95, 180); color: white; padding: 10px 14px; border-radius: 10px; }
nav a { color: white; margin-right: 14px; font-weight: bold; }
main { display: block; padding: 6px 0; }
section, article { background: white; border: 1px solid #c0d4f0; border-radius: 10px; padding: 8px 12px; margin: 10px 0; }
aside { background: rgb(255, 243, 196); padding: 8px 12px; border-radius: 10px; margin: 10px 0; }
footer { color: #555; border-top: 2px solid #c0d4f0; margin-top: 12px; padding-top: 6px; font-size: 14px; }

